<?php
declare(strict_types=1);
require __DIR__.'/bootstrap/app.php';
use App\AI\MeetingCompanionService;
use App\Core\Auth;
use App\Core\Config;
use App\Core\Database;
use App\Core\Security;
use App\Core\Url;
use App\Learning\InstructorWorkspaceService;
$pdo=Database::connect();
$user=Auth::user($pdo);
if(!$user||!Auth::hasRole($pdo,(int)$user['id'],'instructor')){http_response_code(403);exit('Instructor access is required.');}
$workspace=new InstructorWorkspaceService($pdo);
$instructorId=(int)$user['id'];
$error='';$success='';$aiDraft='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
 if(!Security::verifyCsrf($_POST['_csrf']??null))$error='Your session expired. Refresh and try again.';
 else try{
  $action=(string)($_POST['action']??'');
  if($action==='session'){$workspace->createSession($instructorId,(int)($_POST['offering_id']??0),$_POST);$success='Session scheduled. Enrolled learners have been notified.';}
  elseif($action==='reschedule'){$workspace->reschedule($instructorId,(int)($_POST['session_id']??0),(string)($_POST['starts_at']??''),(string)($_POST['ends_at']??''),(string)($_POST['timezone']??'Africa/Kampala'));$success='Session rescheduled and learners notified.';}
  elseif($action==='complete'){$workspace->complete($instructorId,(int)($_POST['session_id']??0));$success='Session marked completed. You can now record attendance.';}
  elseif($action==='cancel'){$workspace->cancel($instructorId,(int)($_POST['session_id']??0));$success='Session cancelled and learners notified.';}
  elseif($action==='attendance'){$workspace->recordAttendance($instructorId,(int)($_POST['session_id']??0),(int)($_POST['learner_id']??0),(string)($_POST['status']??''),(string)($_POST['reason']??''));$success='Attendance saved and added to the audit history.';}
  elseif($action==='companion'){$sessionId=(int)($_POST['session_id']??0);$workspace->assertSession($instructorId,$sessionId);$ai=new MeetingCompanionService($pdo,(string)Config::get('ai.groq_api_key',''),(string)Config::get('ai.groq_model','llama-3.3-70b-versatile'),(int)Config::get('ai.groq_input_budget',6000),(int)Config::get('ai.groq_output_budget',1200),(int)Config::get('ai.groq_daily_requests',20),(int)Config::get('ai.groq_daily_tokens',30000),(bool)Config::get('ai.groq_enabled',true),(int)Config::get('ai.groq_meeting_requests',8),(int)Config::get('ai.groq_meeting_tokens',12000));$draft=$ai->generate($instructorId,$sessionId,(string)($_POST['task']??''),(string)($_POST['notes']??''));$aiDraft=$draft['answer'];}
  else throw new RuntimeException('Unknown instructor workspace action.');
 }catch(Throwable $e){$error=$e->getMessage();}
}
$offerings=$workspace->offerings($instructorId);
$sessions=$workspace->sessions($instructorId);
$csrf=Security::csrfToken();
$esc=static fn($value)=>Security::escape((string)$value);
$formatTime=static function(string $utc,string $timezone):string{try{return (new DateTimeImmutable($utc,new DateTimeZone('UTC')))->setTimezone(new DateTimeZone($timezone))->format('D, d M Y · H:i T');}catch(Throwable){return $utc.' UTC';}};
?>
<!doctype html><html lang="en"><head><base href="<?= $esc(Url::to('/')) ?>"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Instructor workspace · SmartStudyPro</title><link rel="stylesheet" href="<?= $esc(Url::to('/assets/vendor/bootstrap/css/bootstrap.min.css')) ?>"><link rel="stylesheet" href="<?= $esc(Url::to('/assets/css/main.css')) ?>">
<link rel="stylesheet" href="<?= $esc(Url::to('/assets/css/device-responsive.css')) ?>"><style>body{background:var(--ssp-page-bg);color:var(--ssp-text)}.wrap{max-width:1160px;margin:auto;padding:30px 18px}.panel,.session{background:var(--ssp-surface);border:1px solid var(--ssp-border);border-radius:var(--ssp-radius-lg);padding:20px;margin:16px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px}.field label{display:block;font-size:13px;font-weight:650;margin-bottom:6px}.field input,.field select,.field textarea{width:100%;padding:10px;border:1px solid var(--ssp-border);border-radius:var(--ssp-radius-sm);background:var(--ssp-surface);color:var(--ssp-text)}.muted{color:var(--ssp-muted);font-size:13px}.btn-main{background:var(--ssp-accent);color:#fff;border:0;border-radius:var(--ssp-radius-sm);padding:10px 15px;font-weight:700}.roster-row{border-top:1px solid var(--ssp-border);padding:12px 0}.draft{white-space:pre-wrap;background:var(--ssp-surface-muted);border:1px solid var(--ssp-border);border-radius:var(--ssp-radius-sm);padding:16px;color:var(--ssp-text)}.actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}</style></head><body>
<?php include __DIR__.'/nav.php'; ?>
<main class="wrap" id="main-content"><div class="d-flex flex-wrap justify-content-between align-items-center gap-2"><div><h1>Instructor workspace</h1><p class="muted mb-0">Manage only the course offerings assigned to your account.</p></div><a class="btn btn-outline-secondary" href="<?= $esc(Url::to('/meetings')) ?>">My learner sessions</a></div>
<?php if($error!==''):?><div class="alert alert-danger mt-3"><?= $esc($error) ?></div><?php endif;?><?php if($success!==''):?><div class="alert alert-success mt-3"><?= $esc($success) ?></div><?php endif;?>
<?php if($aiDraft!==''):?><section class="panel"><h2 class="h5">AI draft · review before sharing</h2><div class="draft"><?= $esc($aiDraft) ?></div></section><?php endif;?>
<section class="panel"><h2 class="h4">Your assigned course offerings</h2><?php if(!$offerings):?><p class="muted mb-0">No course offerings have been assigned to you yet. Ask an administrator to assign a cohort.</p><?php else:?><div class="row g-3"><?php foreach($offerings as $offering):?><div class="col-md-6 col-xl-4"><article class="border rounded-3 p-3 h-100"><strong><?= $esc($offering['course_title'].' · '.$offering['title']) ?></strong><p class="muted mt-2 mb-0"><?= $esc(str_replace('_',' ',$offering['mode'])) ?> · <?= (int)$offering['learners'] ?> enrolled</p><p class="muted mb-0"><?= $esc($offering['description']) ?></p></article></div><?php endforeach;?></div><?php endif;?></section>
<section class="panel"><h2 class="h4">Schedule a session</h2><p class="muted">Only your assigned live-online and in-person offerings are available. Host links are kept private.</p><?php $schedulable=array_values(array_filter($offerings,static fn($o)=>$o['mode']!=='self_paced'));if(!$schedulable):?><p class="muted">You do not have a live or in-person offering assigned yet.</p><?php else:?><form method="post"><input type="hidden" name="_csrf" value="<?= $esc($csrf) ?>"><input type="hidden" name="action" value="session"><div class="grid"><div class="field"><label>Offering</label><select name="offering_id" required><?php foreach($schedulable as $o):?><option value="<?= (int)$o['id'] ?>"><?= $esc($o['course_title'].' · '.$o['title'].' ('.$o['mode'].')') ?></option><?php endforeach;?></select></div><div class="field"><label>Session title</label><input name="title" maxlength="160" required></div><div class="field"><label>Provider</label><select name="provider"><option value="zoom">Zoom</option><option value="google_meet">Google Meet</option><option value="in_person">In person</option></select></div><div class="field"><label>Timezone (IANA)</label><input name="timezone" value="Africa/Kampala" required></div><div class="field"><label>Starts (local time)</label><input type="datetime-local" name="starts_at" required></div><div class="field"><label>Ends (local time)</label><input type="datetime-local" name="ends_at" required></div><div class="field"><label>Capacity override</label><input type="number" name="capacity" min="1"></div><div class="field"><label>Learner join URL</label><input type="url" name="join_url" placeholder="https://..."></div><div class="field"><label>Host URL (private)</label><input type="url" name="host_url" placeholder="https://..."></div><div class="field"><label>Venue name</label><input name="venue_name"></div><div class="field"><label>Venue address</label><input name="venue_address"></div><div class="field"><label>Venue notes</label><input name="venue_notes"></div><div class="field" style="grid-column:1/-1"><label>Agenda</label><textarea name="agenda" rows="3"></textarea></div></div><p class="mt-3 mb-0"><button class="btn-main">Schedule session</button></p></form><?php endif;?></section>
<section class="panel"><h2 class="h4">Your sessions and learner rosters</h2><?php if(!$sessions):?><p class="muted mb-0">No sessions exist for your assigned offerings yet.</p><?php else:foreach($sessions as $session):?><article class="session"><div class="d-flex flex-wrap justify-content-between gap-2"><div><h3 class="h5 mb-1"><?= $esc($session['course_title'].' · '.$session['title']) ?></h3><p class="muted mb-1"><?= $esc($session['offering_title'].' · '.$formatTime((string)$session['starts_at_utc'],(string)$session['timezone'])) ?></p><span class="badge bg-secondary"><?= $esc($session['status']) ?></span> <span class="badge bg-light text-dark"><?= (int)$session['booked_count'] ?> booked<?= $session['capacity']!==null?' / '.(int)$session['capacity']:'' ?></span></div></div>
<?php if(in_array($session['status'],['scheduled','rescheduled'],true)):?><div class="actions"><form method="post"><input type="hidden" name="_csrf" value="<?= $esc($csrf) ?>"><input type="hidden" name="action" value="complete"><input type="hidden" name="session_id" value="<?= (int)$session['id'] ?>"><button class="btn btn-sm btn-outline-success">Mark completed</button></form><form method="post" onsubmit="return confirm('Cancel this session and notify enrolled learners?')"><input type="hidden" name="_csrf" value="<?= $esc($csrf) ?>"><input type="hidden" name="action" value="cancel"><input type="hidden" name="session_id" value="<?= (int)$session['id'] ?>"><button class="btn btn-sm btn-outline-danger">Cancel</button></form></div><form method="post" class="mt-3"><input type="hidden" name="_csrf" value="<?= $esc($csrf) ?>"><input type="hidden" name="action" value="reschedule"><input type="hidden" name="session_id" value="<?= (int)$session['id'] ?>"><div class="grid"><div class="field"><label>New start</label><input type="datetime-local" name="starts_at" required></div><div class="field"><label>New end</label><input type="datetime-local" name="ends_at" required></div><div class="field"><label>Timezone</label><input name="timezone" value="<?= $esc($session['timezone']) ?>" required></div></div><button class="btn btn-sm btn-outline-primary mt-2">Reschedule</button></form><?php endif;?>
<details class="mt-3"><summary>View roster and record attendance</summary><?php foreach($workspace->roster($instructorId,(int)$session['id']) as $person):?><div class="roster-row"><strong><?= $esc($person['name']) ?></strong><div class="muted"><?= $esc($person['email']) ?> · <?= $esc($person['attendance_status']??'not recorded') ?></div><?php if(in_array($session['status'],['completed','archived'],true)):?><form method="post" class="grid mt-2"><input type="hidden" name="_csrf" value="<?= $esc($csrf) ?>"><input type="hidden" name="action" value="attendance"><input type="hidden" name="session_id" value="<?= (int)$session['id'] ?>"><input type="hidden" name="learner_id" value="<?= (int)$person['user_id'] ?>"><div class="field"><label>Status</label><select name="status"><option value="present">Present</option><option value="late">Late</option><option value="absent">Absent</option><option value="excused">Excused</option></select></div><div class="field"><label>Reason (required)</label><input name="reason" required></div><div class="field d-flex align-items-end"><button class="btn btn-sm btn-outline-primary">Save attendance</button></div></form><?php endif;?></div><?php endforeach;?><?php if(!$workspace->roster($instructorId,(int)$session['id'])):?><p class="muted mt-2">No confirmed bookings for this session.</p><?php endif;?></details>
<?php if(in_array($session['status'],['scheduled','rescheduled'],true)):?><form method="post" class="mt-3"><input type="hidden" name="_csrf" value="<?= $esc($csrf) ?>"><input type="hidden" name="action" value="companion"><input type="hidden" name="session_id" value="<?= (int)$session['id'] ?>"><div class="field"><label>Meeting companion task</label><input name="task" required maxlength="4000" placeholder="Draft a 45-minute agenda with group activities"></div><div class="field mt-2"><label>Instructor notes</label><textarea name="notes" rows="3" maxlength="12000"></textarea></div><button class="btn btn-sm btn-outline-primary mt-2">Generate AI draft</button></form><?php endif;?></article><?php endforeach;endif;?></section>
</main></body></html>
